"""Walk a downstream Harness project and return a typed snapshot of artifacts."""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path


@dataclass
class FeatureState:
    """State for one feature, sourced from per-feature `docs/features/<id>/state.json`
    (post-plan) or `docs/state/features.json[<id>]` index entry (pre-plan)."""

    feature_id: str
    raw: dict  # full record from state file (tolerant of schema evolution)
    story_path: Path | None = None
    research_path: Path | None = None
    requirements_path: Path | None = None
    plan_path: Path | None = None
    validation_path: Path | None = None  # latest VALIDATION-*.md by mtime
    review_path: Path | None = None
    test_cases_path: Path | None = None
    design_path: Path | None = None     # docs/features/<id>/DESIGN.md — ux-agent output
    design_dir: Path | None = None      # docs/design/<id>/ — per-feature export bundle
    runbook_paths: list[Path] = field(default_factory=list)
    # Evidence-pass companion artefacts, written by the implementation-agent
    # alongside the impl_evidence state block:
    #   EVIDENCE-ROUNDS.md      — per-round table appended each fix-loop iteration
    #   EVIDENCE-ESCALATION.md  — round-3 persistent-failure report
    evidence_rounds_path: Path | None = None
    evidence_escalation_path: Path | None = None

    @property
    def title(self) -> str:
        """Extract title from story file H1, or fallback to feature id."""
        if self.story_path and self.story_path.exists():
            try:
                first_line = self.story_path.read_text(encoding="utf-8").splitlines()[0]
                if first_line.startswith("# "):
                    # Strip "# Story: BKM-01 — " prefix; keep the human title
                    text = first_line[2:].strip()
                    if " — " in text:
                        text = text.split(" — ", 1)[1]
                    elif ": " in text and text.startswith("Story:"):
                        text = text.split(": ", 1)[1]
                        if " — " in text:
                            text = text.split(" — ", 1)[1]
                    return text
            except Exception:
                pass
        return self.feature_id


@dataclass
class ProjectSnapshot:
    """Everything site builder needs from a downstream project."""

    root: Path
    claude_md_path: Path | None
    rtm_path: Path | None
    features: dict[str, FeatureState] = field(default_factory=dict)
    adr_paths: list[Path] = field(default_factory=list)
    session_paths: list[Path] = field(default_factory=list)
    config_paths: list[Path] = field(default_factory=list)
    rule_paths: list[Path] = field(default_factory=list)
    activity_paths: list[Path] = field(default_factory=list)
    state_raw: dict = field(default_factory=dict)

    @property
    def project_title(self) -> str:
        """Project title from CLAUDE.md H1 or the root directory name."""
        if self.claude_md_path and self.claude_md_path.exists():
            try:
                first_line = self.claude_md_path.read_text(encoding="utf-8").splitlines()[0]
                if first_line.startswith("# "):
                    return first_line[2:].strip()
            except Exception:
                pass
        return self.root.name


def discover(root: Path) -> ProjectSnapshot:
    """Walk `root` and assemble a ProjectSnapshot."""
    root = root.resolve()
    snap = ProjectSnapshot(
        root=root,
        claude_md_path=_first_existing(root / "CLAUDE.md"),
        rtm_path=_first_existing(root / "docs" / "requirements" / "RTM.md"),
    )

    # Parse index file (tolerant) — cross-feature status mirror; always exists
    # once `/arh-init` has run.
    state_file = root / "docs" / "state" / "features.json"
    if state_file.exists():
        try:
            snap.state_raw = json.loads(state_file.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            snap.state_raw = {}

    # Walk docs/features/<id>/ — per-feature canonical dirs (post-plan)
    features_dir = root / "docs" / "features"
    feature_ids: set[str] = set()
    if features_dir.is_dir():
        for entry in features_dir.iterdir():
            if entry.is_dir() and not entry.name.startswith("_") and not entry.name.startswith("."):
                feature_ids.add(entry.name)

    # Also include any feature ids that appear in index but lack a features/<id>/
    # dir (pre-plan features — story / research only).
    feature_ids.update(k for k in snap.state_raw if isinstance(k, str))

    for fid in sorted(feature_ids):
        # Two-tier state read: per-feature file is canonical when present
        # (post-plan); otherwise fall back to index entry (pre-plan).
        fdir = features_dir / fid
        per_feature_state = fdir / "state.json"
        if per_feature_state.exists():
            try:
                record = json.loads(per_feature_state.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                record = snap.state_raw.get(fid, {})
        else:
            record = snap.state_raw.get(fid, {})
        fs = FeatureState(feature_id=fid, raw=record)
        fs.story_path = _first_existing(root / "docs" / "stories" / f"{fid}.md")
        fs.research_path = _first_existing(root / "docs" / "research" / f"{fid}.md")
        fs.requirements_path = _first_existing(fdir / "REQUIREMENTS.md")
        fs.plan_path = _first_existing(fdir / "PLAN.md")
        fs.review_path = _first_existing(fdir / "REVIEW.md")
        fs.design_path = _first_existing(fdir / "DESIGN.md")
        fs.test_cases_path = _first_existing(root / "docs" / "test-cases" / f"{fid}.json")
        # Latest VALIDATION-*.md by mtime
        if fdir.is_dir():
            val_files = sorted(fdir.glob("VALIDATION-*.md"), key=lambda p: p.stat().st_mtime, reverse=True)
            if val_files:
                fs.validation_path = val_files[0]
        # Per-feature design export bundle: docs/design/<id>/
        per_feature_design = root / "docs" / "design" / fid
        if per_feature_design.is_dir():
            fs.design_dir = per_feature_design
        if fdir.is_dir():
            # Evidence-pass artefacts (round table + escalation report)
            fs.evidence_rounds_path = _first_existing(fdir / "EVIDENCE-ROUNDS.md")
            fs.evidence_escalation_path = _first_existing(fdir / "EVIDENCE-ESCALATION.md")
        # Runbooks: docs/runbooks/<id>-*.md
        runbooks_dir = root / "docs" / "runbooks"
        if runbooks_dir.is_dir():
            fs.runbook_paths = sorted(runbooks_dir.glob(f"{fid}-*.md"))
        snap.features[fid] = fs

    # ADRs
    adr_dir = root / "docs" / "adr"
    if adr_dir.is_dir():
        snap.adr_paths = sorted(p for p in adr_dir.glob("*.md") if p.is_file())

    # Sessions
    sessions_dir = root / "docs" / "sessions"
    if sessions_dir.is_dir():
        snap.session_paths = sorted(p for p in sessions_dir.glob("*.md") if p.is_file())

    # Config (YAML) files
    config_dir = root / "docs" / "config"
    if config_dir.is_dir():
        snap.config_paths = sorted(p for p in config_dir.glob("*.yaml") if p.is_file())

    # Internal rules (only surfaced when --include-internal)
    rules_dir = root / ".claude" / "rules"
    if rules_dir.is_dir():
        snap.rule_paths = sorted(p for p in rules_dir.rglob("*.md") if p.is_file())

    # Activity JSONLs — docs/activity/<YYYY-MM>.jsonl (one file per month)
    activity_dir = root / "docs" / "activity"
    if activity_dir.is_dir():
        snap.activity_paths = sorted(p for p in activity_dir.glob("*.jsonl") if p.is_file())

    return snap


def _first_existing(p: Path) -> Path | None:
    return p if p.exists() else None
